local CharcoalBurner = {}
local PRODUCTS = {
    soft_charcoal = { name = "Mehko oglje", woodCost = 2, time = 1, cost = 8, burnQuality = 30, description = "Mehko oglje iz mehkega lesa." },
    hardwood_charcoal = { name = "Trdodrevno oglje", woodCost = 3, time = 3, cost = 22, burnQuality = 50, prestige = 1, description = "Trdodrevno oglje z visoko toplotno močjo." },
    lump_charcoal = { name = "Komensko oglje", woodCost = 3, clayCost = 1, time = 4, cost = 55, burnQuality = 70, prestige = 2, description = "Komensko oglje iz glinenih peči." },
    refined_charcoal = { name = "Rafinirano oglje", woodCost = 4, clayCost = 1, time = 6, cost = 130, burnQuality = 85, prestige = 5, happiness = 1, description = "Rafinirano oglje za smodnik." },
    silver_dust_charcoal = { name = "Srebrno prašni oglje", woodCost = 4, clayCost = 1, silverCost = 1, time = 9, cost = 320, burnQuality = 95, prestige = 11, happiness = 2, description = "Oglje s srebrnim prahom za fine smodnike." },
    royal_pure_charcoal = { name = "Kraljevski čisto oglje", woodCost = 6, clayCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 13, cost = 850, burnQuality = 100, prestige = 30, happiness = 7, description = "Veliko kraljevsko čisto oglje z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Ogljarska delavnica", cost = { gold = 220, wood = 150 }, upkeep = 5, qualityBonus = 5 },
    kiln = { name = "Ogljarska peč", cost = { gold = 700, wood = 280, stone = 350, clay = 8 }, upkeep = 16, qualityBonus = 18 },
    retort = { name = "Retorta", cost = { gold = 1800, wood = 400, stone = 600, silver = 30, iron = 8 }, upkeep = 42, qualityBonus = 30 },
    royal_charcoal_atelier = { name = "Kraljevski atelje oglja", cost = { gold = 7500, wood = 800, stone = 1500, gold = 60, jewel = 20 }, upkeep = 150, qualityBonus = 55, prestigeBonus = 35 },
}
CharcoalBurner.woodStock = 22; CharcoalBurner.clayStock = 14; CharcoalBurner.silverStock = 8; CharcoalBurner.goldStock = 6; CharcoalBurner.jewelStock = 6
CharcoalBurner.productStock = {}; CharcoalBurner.buildings = {}; CharcoalBurner.maker = nil; CharcoalBurner.activeMaking = {}; CharcoalBurner.totalProducts = 0; CharcoalBurner.dayTimer = 0
function CharcoalBurner.init() CharcoalBurner.woodStock=22; CharcoalBurner.clayStock=14; CharcoalBurner.silverStock=8; CharcoalBurner.goldStock=6; CharcoalBurner.jewelStock=6; CharcoalBurner.productStock={}; CharcoalBurner.buildings={}; CharcoalBurner.maker=nil; CharcoalBurner.activeMaking={}; CharcoalBurner.totalProducts=0; CharcoalBurner.dayTimer=0; print("[CharcoalBurner] Royal Charcoal Burner System initialized (6 products, 4 buildings)") end
function CharcoalBurner.hireMaker(n,s) s=s or math.random(50,90); local c=450+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CharcoalBurner.maker={name=n or ("Ogljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ogljar najet: %s (spretnost: %d)",CharcoalBurner.maker.name,s),"success") end; return true end
function CharcoalBurner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CharcoalBurner.build(id) local ok,e=CharcoalBurner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CharcoalBurner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CharcoalBurner.getQualityBonus() local b=0; for _,bd in ipairs(CharcoalBurner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CharcoalBurner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and CharcoalBurner.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.clayCost and CharcoalBurner.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.silverCost and CharcoalBurner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CharcoalBurner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CharcoalBurner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #CharcoalBurner.buildings==0 then return false,"Potrebna delavnica" end; if not CharcoalBurner.maker then return false,"Potreben ogljar" end; return true end
function CharcoalBurner.make(pt,qty) qty=qty or 10; local ok,e=CharcoalBurner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then CharcoalBurner.woodStock=CharcoalBurner.woodStock-d.woodCost*qty end; if d.clayCost then CharcoalBurner.clayStock=CharcoalBurner.clayStock-d.clayCost*qty end; if d.silverCost then CharcoalBurner.silverStock=CharcoalBurner.silverStock-d.silverCost*qty end; if d.goldCost then CharcoalBurner.goldStock=CharcoalBurner.goldStock-d.goldCost*qty end; if d.jewelCost then CharcoalBurner.jewelStock=CharcoalBurner.jewelStock-d.jewelCost*qty end; local t=d.time; if CharcoalBurner.maker then t=math.max(1,t-math.floor(CharcoalBurner.maker.skill/12)) end; table.insert(CharcoalBurner.activeMaking,{id="charcoal_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,burnQuality=d.burnQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CharcoalBurner.completeMaking(m) local q=1.0+(CharcoalBurner.getQualityBonus()/100); if CharcoalBurner.maker then q=q+(CharcoalBurner.maker.skill/180) end; q=math.min(2.0,q); CharcoalBurner.productStock[m.productType]=(CharcoalBurner.productStock[m.productType] or 0)+m.quantity; CharcoalBurner.totalProducts=CharcoalBurner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CharcoalBurner.maker then CharcoalBurner.maker.itemsMade=CharcoalBurner.maker.itemsMade+m.quantity; if math.random()<0.20 then CharcoalBurner.maker.skill=math.min(100,CharcoalBurner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oglje izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"charcoal.completed",{productName=m.productName,burnQuality=m.burnQuality}) end end
function CharcoalBurner.update(dt) if not _G.state then return end; CharcoalBurner.dayTimer=CharcoalBurner.dayTimer+dt; if CharcoalBurner.dayTimer>=30 then CharcoalBurner.dayTimer=0; for i=#CharcoalBurner.activeMaking,1,-1 do local m=CharcoalBurner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CharcoalBurner.completeMaking(m); table.remove(CharcoalBurner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CharcoalBurner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CharcoalBurner.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CharcoalBurner.getStats() return {woodStock=CharcoalBurner.woodStock,clayStock=CharcoalBurner.clayStock,silverStock=CharcoalBurner.silverStock,goldStock=CharcoalBurner.goldStock,jewelStock=CharcoalBurner.jewelStock,productStock=CharcoalBurner.productStock,numBuildings=#CharcoalBurner.buildings,hasMaker=CharcoalBurner.maker~=nil,makerName=CharcoalBurner.maker and CharcoalBurner.maker.name or "—",makerSkill=CharcoalBurner.maker and CharcoalBurner.maker.skill or 0,activeMaking=#CharcoalBurner.activeMaking,totalProducts=CharcoalBurner.totalProducts} end
return CharcoalBurner
